def topo_sort(graph):
    visited = set()
    rec_stack = set()
    order = []

    def dfs(node):
        if node in rec_stack:
            return False
        if node in visited:
            return True
        rec_stack.add(node)
        for dep in graph.get(node, []):
            if not dfs(dep):
                return False
        rec_stack.discard(node)
        visited.add(node)
        order.append(node)
        return True

    all_nodes = set()
    for node, deps in graph.items():
        all_nodes.add(node)
        all_nodes.update(deps)

    for node in all_nodes:
        if node not in visited:
            if not dfs(node):
                return None

    return order
