def normalize(path):
    if not path:
        return '.'

    is_abs = path.startswith('/')
    parts = path.split('/')
    res = []

    for p in parts:
        if p == '' or p == '.':
            continue
        elif p == '..':
            if res:
                res.pop()
            elif not is_abs:
                res.append('..')
            # else: absolute path, .. at root does nothing
        else:
            res.append(p)

    if is_abs:
        return '/' + '/'.join(res)
    else:
        if not res:
            return '.'
        return '/'.join(res)
```

