def merge_dicts(a, b):
    if not isinstance(a, dict) or not isinstance(b, dict):
        return {}
    merged = {}
    for key in set(a) | set(b):
        if key in a and key in b:
            if isinstance(a[key], dict) and isinstance(b[key], dict):
                merged[key] = merge_dicts(a[key], b[key])
            else:
                merged[key] = b[key]
        elif key in a:
            merged[key] = a[key]
        else:
            merged[key] = b[key]
    return merged
