def deep_get(obj, path, default=None):
    parts = path.split('.')
    current = obj
    for part in parts:
        if isinstance(current, dict):
            if part in current:
                current = current[part]
            else:
                return default
        elif isinstance(current, list):
            try:
                idx = int(part)
            except ValueError:
                return default
            try:
                current = current[idx]
            except IndexError:
                return default
        else:
            return default
    return current
