import re


def parse_duration(s):
    if not isinstance(s, str):
        raise ValueError("Invalid duration string")
    s = s.strip()
    if not s:
        raise ValueError("Invalid duration string")
    total = 0
    for match in re.finditer(r"(\d+)([hmsd])", s):
        value = int(match.group(1))
        unit = match.group(2)
        if unit == "h":
            total += value * 3600
        elif unit == "m":
            total += value * 60
        elif unit == "s":
            total += value
        elif unit == "d":
            total += value * 86400
    remaining = re.sub(r"(\d+)([hmsd])", "", s)
    if remaining:
        raise ValueError("Invalid duration string")
    return total

