export function debounceState(): {
  pending: boolean;
  mark(): void;
  clear(): void;
} {
  let timeoutId: number | undefined;
  let _pending = false;

  const mark = (): void => {
    _pending = true;
    if (timeoutId !== undefined) clearTimeout(timeoutId);
    timeoutId = setTimeout(() => {
      _pending = false;
    }, 300);
  };

  const clear = (): void => {
    if (timeoutId !== undefined) clearTimeout(timeoutId);
    timeoutId = undefined;
    _pending = false;
  };

  return { pending: _pending, mark, clear };
}

